// Assertions about the documentation of specloop at /made/specloop/docs/:
// the guides built from the specloop repository, the reference generated by
// generators/specloop-reference.mjs, and their links.
//
// `npm run test:sites` builds the sites into `.cache/test-dist` and runs
// `coffer check` on them before these tests start, and they read that output
// together with the checkout of the repository that the build fetched
// (`.cache/repos/specloop`).
//
// NETWORK. The docs source of specloop is the public repository
// https://github.com/ba3a/specloop.git (`ref: main`), cloned read-only over
// HTTPS by the build itself. coffer never reuses a stale checkout (see
// github.com/ba3a/coffer/blob/v0.1.0/docs/docs-sources.md): when the repository cannot be reached,
// `coffer build` fails with a message that names the project and the address,
// and the tests do not start. So these tests never skip: either the build
// delivered the docs, and they are asserted, or the run has already failed.
// The generator itself is tested without a network in generators/test, against
// a small fixture. Because `ref` is a moving branch, the numbers below come
// from the checkout that was built (never from constants), and a change in the
// repository can only fail a test by changing its table of contents without
// the `order` of project.yaml (the message says so).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import { parse as parseYaml } from 'yaml';

const root = fileURLToPath(new URL('../..', import.meta.url));
const dist = join(root, '.cache', 'test-dist', 'ba3a.dev');
const checkout = join(root, '.cache', 'repos', 'specloop');
const docsUrl = '/made/specloop/docs/';
const generator = join(root, 'generators', 'specloop-reference.mjs');

/** @param {string} file Path relative to the output of the site. @returns {string} */
const page = (file) => readFileSync(join(dist, file), 'utf8');

/** @param {string} url A site address. @returns {string} The file of the page in the output. */
const fileOf = (url) => join(dist, ...url.split('/').filter(Boolean), 'index.html');

const manifest = JSON.parse(page('.coffer-manifest.json'));
const project = manifest.projects.find((/** @type {{ slug: string }} */ candidate) => candidate.slug === 'specloop');
const declaration = parseYaml(readFileSync(join(root, 'content', 'ba3a.dev', 'projects', 'specloop', 'project.yaml'), 'utf8'));

/** The Markdown files named in the table of contents of the README of the repository, in order. */
function tableOfContents() {
  const readme = readFileSync(join(checkout, 'docs', 'README.md'), 'utf8');
  return [...readme.matchAll(/^\s*[-*]\s+\[[^\]]+\]\(([A-Za-z0-9._-]+\.md)(?:#[^)]*)?\)/gm)].map((match) => match[1]);
}

/** @param {string} html @returns {string[]} The values of the `href` attributes. */
const hrefs = (html) => [...html.matchAll(/\shref="([^"]*)"/g)].map((match) => match[1]);

/** @param {string} text @returns {string} */
const escapeHtml = (text) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** The reference as the generator makes it from the built checkout (read only). */
function generated() {
  const out = mkdtempSync(join(tmpdir(), 'specloop-docs-test-'));
  try {
    const run = spawnSync(process.execPath, [generator, checkout, out], { encoding: 'utf8' });
    assert.equal(run.status, 0, `the generator failed: ${run.stderr}`);
    return JSON.parse(readFileSync(join(out, 'reference.json'), 'utf8'));
  } finally {
    rmSync(out, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
  }
}

/** The number of keys of an object at every depth, counted the plain way. */
function countKeys(value) {
  let total = 0;
  for (const child of Object.values(value)) {
    total += 1;
    if (typeof child === 'object' && child !== null && !Array.isArray(child)) total += countKeys(child);
  }
  return total;
}

test('the docs of specloop are configured to come from ba3a/specloop on GitHub', () => {
  assert.equal(declaration.docs.source.git, 'https://github.com/ba3a/specloop.git');
  assert.equal(declaration.docs.source.ref, 'main');
  assert.equal(declaration.docs.reference.format, 'json');
  assert.equal(declaration.docs.reference.command[1], '{site}/generators/specloop-reference.mjs');
  assert.deepEqual(project.docs.source.git, declaration.docs.source.git);
  assert.equal(project.docs.github, 'ba3a/specloop');
  assert.match(project.docs.source.sha, /^[0-9a-f]{40}$/);
  assert.ok(existsSync(join(checkout, 'docs', 'README.md')), 'the build left the checkout in .cache/repos/specloop');
});

test('the docs index and the guides are built from the docs folder of the repository', () => {
  assert.ok(existsSync(fileOf(docsUrl)), 'the docs index exists');
  const sources = readdirSync(join(checkout, 'docs')).filter((name) => name.endsWith('.md'));
  assert.ok(sources.length > 3, 'the repository has guides');
  const published = project.docs.pages.map((/** @type {{ source: string }} */ entry) => entry.source).sort();
  assert.deepEqual(published, sources.map((name) => `docs/${name}`).sort(), 'every guide of the repository is a page, and nothing else');
  for (const entry of project.docs.pages) {
    assert.ok(existsSync(join(dist, entry.file)), `${entry.url} was written`);
    assert.match(page(entry.file), /<h1[^>]*>[^<]+<\/h1>/, `${entry.url} has a title`);
  }
  assert.equal(project.docs.pages[0].source, 'docs/README.md', 'the README is the docs index');
  assert.equal(project.docs.pages[0].url, docsUrl);
});

test('the guides are in the order of the table of contents of the README', () => {
  const toc = tableOfContents();
  assert.ok(toc.length >= 10, 'the README lists the guides');
  const configured = declaration.docs.guides[0].order;
  assert.deepEqual(
    configured,
    toc,
    'the table of contents of docs/README.md in ba3a/specloop changed: update docs.guides[0].order in content/ba3a.dev/projects/specloop/project.yaml to match',
  );
  const built = project.docs.pages.slice(1).map((/** @type {{ source: string }} */ entry) => entry.source.replace(/^docs\//, ''));
  assert.deepEqual(built.slice(0, toc.length), toc, 'the pages follow the table of contents');
  // The sidebar of the docs index lists the pages in the same order, the reference last.
  const sidebar = /<nav[^>]*documentation pages[\s\S]*?<\/nav>/.exec(page(project.docs.pages[0].file))?.[0] ?? '';
  const listed = hrefs(sidebar).filter((href) => href.startsWith(docsUrl));
  assert.deepEqual(listed, [...project.docs.pages.map((/** @type {{ url: string }} */ entry) => entry.url), project.docs.reference.url]);
});

test('links between guides are site links that lead to pages and anchors that exist', () => {
  const indexPage = page(project.docs.pages[0].file);
  const pagesByUrl = new Map(project.docs.pages.map((/** @type {{ url: string, file: string }} */ entry) => [entry.url, entry.file]));
  // The table of contents of the README links every guide, with site addresses.
  for (const name of tableOfContents()) {
    const url = `${docsUrl}${name.replace(/\.md$/, '')}/`;
    assert.ok(pagesByUrl.has(url), `${url} is a page`);
    assert.ok(hrefs(indexPage).includes(url), `the docs index links ${url}`);
  }
  let checked = 0;
  for (const entry of project.docs.pages) {
    const html = page(entry.file);
    for (const href of hrefs(html)) {
      assert.ok(/^https?:/.test(href) || !/\.md(#|$)/.test(href),`${entry.url}: ${href} is still a Markdown link`);
      if (!href.startsWith(docsUrl)) continue;
      const [path, hash] = href.split('#');
      const target = path === docsUrl || pagesByUrl.has(path) ? page((pagesByUrl.get(path) ?? '')) : null;
      if (path === project.docs.reference.url) {
        assert.ok(existsSync(fileOf(path)), `${entry.url}: ${href} leads to the reference`);
        continue;
      }
      assert.notEqual(target, null, `${entry.url}: ${href} leads to a page that exists`);
      if (hash) assert.ok(target.includes(`id="${hash}"`), `${entry.url}: ${href} leads to an anchor that exists`);
      checked += 1;
    }
  }
  assert.ok(checked >= 20, `the guides link each other (${checked} links checked)`);
});

test('the link to ../CHANGELOG.md leads to the file on GitHub', () => {
  assert.ok(existsSync(join(checkout, 'CHANGELOG.md')), 'the repository has a CHANGELOG.md');
  const readme = readFileSync(join(checkout, 'docs', 'README.md'), 'utf8');
  assert.match(readme, /\]\(\.\.\/CHANGELOG\.md\)/, 'the README of the guides links ../CHANGELOG.md');
  const indexHtml = page(project.docs.pages[0].file);
  assert.ok(hrefs(indexHtml).includes('https://github.com/ba3a/specloop/blob/main/CHANGELOG.md'));
  assert.match(indexHtml, /<a href="https:\/\/github\.com\/ba3a\/specloop\/blob\/main\/CHANGELOG\.md"[^>]*>changelog<\/a>/);
  assert.ok(hrefs(indexHtml).includes('https://github.com/ba3a/specloop/blob/main/README.md'), 'the link to ../README.md leads to GitHub too');
  for (const entry of project.docs.pages) {
    for (const href of hrefs(page(entry.file))) assert.ok(!/(^|\/)CHANGELOG\.md/.test(href) || href.startsWith('https://github.com/ba3a/specloop/'), `${entry.url}: ${href}`);
  }
});

test('the reference lists every slash command and every configuration key', () => {
  const reference = generated();
  const byTitle = new Map(reference.sections.map((/** @type {{ title: string, items: unknown[] }} */ section) => [section.title, section.items]));
  /** @type {{ name: string, anchor: string, undocumented: boolean }[]} */
  const items = reference.sections.flatMap((/** @type {{ items: unknown[] }} */ section) => section.items);

  // Counts from the checkout itself, counted the plain way.
  const commandFiles = readdirSync(join(checkout, 'kit', 'commands')).filter((name) => name.endsWith('.md'));
  const defaults = JSON.parse(readFileSync(join(checkout, 'kit', 'specloop', 'defaults.json'), 'utf8'));
  assert.ok(commandFiles.length >= 5);
  assert.equal(byTitle.get('Slash commands')?.length, commandFiles.length, 'every command of kit/commands is in the reference');
  assert.equal(byTitle.get('Configuration keys')?.length, countKeys(defaults), 'every key of defaults.json is in the reference');
  assert.ok((byTitle.get('Environment variables')?.length ?? 0) >= 1);

  // The page lists them all, and the manifest agrees.
  const html = page(project.docs.reference.file);
  assert.equal(project.docs.reference.items, items.length);
  for (const entry of items) {
    assert.ok(html.includes(`id="${entry.anchor}"`), `the reference page has ${entry.name}`);
    assert.ok(html.includes(`>${escapeHtml(entry.name)}</a>`), `the reference page shows the name ${entry.name}`);
  }
  const prefix = defaults.commandPrefix;
  for (const file of commandFiles) assert.ok(html.includes(`>/${prefix}${file.slice(0, -3)}</a>`), `the command ${file} is shown with the default prefix`);
  assert.ok(html.includes(`default prefix &quot;${prefix}&quot;`), 'the prefix is said to be configurable');
});

test('every item without a description is flagged on the page, in the manifest and in the build report', () => {
  const reference = generated();
  /** @type {{ name: string, anchor: string, undocumented: boolean, description?: string }[]} */
  const items = reference.sections.flatMap((/** @type {{ items: unknown[] }} */ section) => section.items);
  const flagged = items.filter((entry) => entry.undocumented).map((entry) => entry.name);
  const html = page(project.docs.reference.file);
  assert.deepEqual([...project.docs.reference.undocumented].sort(), flagged.slice().sort(), 'the manifest lists the undocumented items');
  for (const entry of items) {
    const article = new RegExp(`<article class="ref-item[^"]*" id="${entry.anchor.replace(/[.]/g, '\\.')}">[\\s\\S]*?</article>`).exec(html)?.[0];
    assert.ok(article, `${entry.name} has an article`);
    assert.equal(article.includes('Not documented'), entry.undocumented, `${entry.name}: the note "Not documented" follows the flag`);
    if (!entry.undocumented) assert.ok(entry.description && entry.description.length > 0, `${entry.name} has a description`);
  }
  const report = JSON.parse(readFileSync(join(root, '.coffer', 'report.json'), 'utf8'));
  const warnings = report.warnings.map((/** @type {{ message: string }} */ warning) => warning.message).filter((/** @type {string} */ message) => message.includes('projects/specloop/project.yaml') && message.includes('docs.reference'));
  for (const name of flagged) {
    assert.ok(
      warnings.some((/** @type {string} */ message) => message.includes(`"${name}"`) && message.includes('has no documentation')),
      `the build report lists ${name}`,
    );
  }
  assert.equal(warnings.length, flagged.length, 'and nothing else about the reference');
});

test('the page of specloop links to its docs', () => {
  const tool = page('made/specloop/index.html');
  assert.ok(hrefs(tool).includes(docsUrl), 'the project page links the docs');
  assert.ok(tool.includes('project-fact-docs'));
  assert.ok(existsSync(fileOf(docsUrl)), 'and the link leads to a page');
});
